CustomField.formula:
CEILING(
IF(
    NOT(ISBLANK(Cancelled_Date__c)) && Cancelled_Date__c > Contract_Date__c && Cancelled_Reason__c!="Package Upgrade",
    (
  (YEAR(Cancelled_Date__c) - YEAR(Contract_Date__c)) * 12
) + 
(
  MONTH(Cancelled_Date__c) - MONTH(Contract_Date__c)
) +
(
  (DAY(Cancelled_Date__c) - DAY(Contract_Date__c)) / 30.0
)
,
(
  (YEAR(TODAY()) - YEAR(Contract_Date__c)) * 12
) + 
(
  MONTH(TODAY()) - MONTH(Contract_Date__c)
) +
(
  (DAY(TODAY()) - DAY(Contract_Date__c)) / 30.0
)

))
